<template>
              <UCard class="flex h-full min-h-0 flex-col rounded-none ring-0" :ui="{ body: 'min-h-0 flex-1 overflow-y-auto' }"><template #header><div class="flex items-center justify-between"><h3 class="font-semibold">{{ $t("script.title.lines") }} <span class="text-muted">{{ countText(lines.length) }}</span></h3><UButton icon="i-material-symbols-add" :label="$t('script.action.add')" size="sm" variant="soft" @click="emit('add')"/></div></template><p v-if="!lines.length" class="py-5 text-center text-sm text-muted">{{ $t("script.message.add_lines") }}</p><div v-else class="space-y-2"><div v-for="(line,i) in lines" :key="line.id" class="flex w-full flex-wrap items-start gap-2 rounded-lg border p-3 text-left" :class="activeId===line.id?'border-primary/50 bg-primary/10':'border-default'"><button class="-m-1 flex min-w-0 flex-1 items-start gap-3 rounded-md p-1 text-left transition-colors hover:bg-elevated active:bg-accented" @click="emit('select',line.id)"><span class="text-sm text-muted">{{ i+1 }}</span><span class="min-w-0"><UBadge v-if="(line.reviewStatus??'pending')==='pending'" size="xs" color="warning" variant="subtle" class="mb-1">{{ $t("script.status.needs_review") }}</UBadge><span class="block line-clamp-2 text-sm">{{ line.text||$t('script.label.new_line') }}</span><span class="mt-1 block font-mono text-sm text-muted">{{ line.start===null?$t('script.label.no_range'):fmt(line.start)+' – '+fmt(line.end) }}</span></span></button><UButton icon="i-material-symbols-play-arrow" :label="$t('script.action.view_range')" :aria-label="$t('script.aria.view_range')" size="xs" variant="soft" class="shrink-0" :disabled="!duration||line.start===null||line.end===null||line.end<=line.start||line.end>duration" @click="emit('play',line.id)"/></div></div></UCard>
</template>
<script setup lang="ts">
import { countText } from "bmo-ui/app/domain/numbers";
interface Row {id:string;text:string;notes:string;reviewStatus?:'pending'|'done';start:number|null;end:number|null}
defineProps<{lines:Row[];activeId:string;duration:number}>();
const emit=defineEmits<{select:[id:string];play:[id:string];add:[]}>();
const fmt=(n:number|null)=>{if(n===null)return '';const ms=Math.round(n*1000);return `${Math.floor(ms/60000).toString().padStart(2,'0')}:${((ms%60000)/1000).toFixed(3).padStart(6,'0')}`;};
</script>
